/* @lc app=leetcode id=2471 lang=kotlin */ class Solution { fun minimumOperations(root: TreeNode?): Int = generateSequence(listOf(root!!)) { f -> f.flatMap { listOfNotNull(it.left, it.right) }.takeIf { it.isNotEmpty() } }.sumOf { l -> l.map { it.`val` }.let { v -> v.sorted().withIndex().associate { (i, x) -> x to i }.let { pos -> BooleanArray(v.size).let { seen -> v.size - v.indices.count { i -> !seen[i] && generateSequence(i) { pos[v[it]]!!.takeIf { j -> !seen[j] } }.onEach { seen[it] = true }.count() > 0 } } } } } }